import 'fake-indexeddb/auto';

import { beforeEach, describe, expect, it } from 'vitest';

import {
  clearBase,
  getBase,
  getConflictBackup,
  hasLegacyBase,
  migrateLegacyBase,
  saveBase,
  saveConflictBackup,
} from '../../src/storage/syncBase';

const bytes = (fill: number): Uint8Array => new Uint8Array([fill, fill, fill]);

/** Drop the whole sync database so each test starts empty. */
function reset(): Promise<void> {
  return new Promise((resolve) => {
    const request = indexedDB.deleteDatabase('upm-sync');
    request.onsuccess = () => resolve();
    request.onerror = () => resolve();
    request.onblocked = () => resolve();
  });
}

/** Write the pre-Phase-9 `base` key, creating the store first if needed. */
async function writeLegacyBase(payload: Uint8Array): Promise<void> {
  await getBase('warmup');
  await new Promise<void>((resolve, reject) => {
    const open = indexedDB.open('upm-sync', 1);
    open.onerror = () => reject(open.error);
    open.onsuccess = () => {
      const db = open.result;
      const tx = db.transaction('blobs', 'readwrite');
      tx.objectStore('blobs').put({ key: 'base', bytes: payload, timestamp: Date.now() });
      tx.oncomplete = () => {
        db.close();
        resolve();
      };
      tx.onerror = () => {
        db.close();
        reject(tx.error);
      };
      tx.onabort = () => {
        db.close();
        reject(tx.error);
      };
    };
  });
}

beforeEach(async () => {
  await reset();
});

describe('sync base keys', () => {
  it('isolates the base per database id', async () => {
    await saveBase('db-1', bytes(1));
    await saveBase('db-2', bytes(2));

    expect(await getBase('db-1')).toEqual(bytes(1));
    expect(await getBase('db-2')).toEqual(bytes(2));
    expect(await getBase('db-3')).toBeNull();

    await clearBase('db-1');
    expect(await getBase('db-1')).toBeNull();
    expect(await getBase('db-2')).toEqual(bytes(2));
  });
});

describe('legacy base migration', () => {
  it('moves the single-database base to the given id once', async () => {
    // Simulate the pre-Phase-9 `base` key directly.
    await writeLegacyBase(bytes(7));

    expect(await hasLegacyBase()).toBe(true);
    expect(await migrateLegacyBase('db-1')).toBe(true);
    expect(await getBase('db-1')).toEqual(bytes(7));
    expect(await hasLegacyBase()).toBe(false);
    expect(await migrateLegacyBase('db-1')).toBe(false);
  });
});

describe('conflict backups', () => {
  it('keys backups per database and prunes the oldest', async () => {
    const keys: string[] = [];
    for (let i = 0; i < 12; i += 1) {
      keys.push(await saveConflictBackup('db-1', bytes(i)));
    }
    await saveConflictBackup('db-2', bytes(9));

    // Only the newest 10 for db-1 survive.
    const first = await getConflictBackup(keys[0]!);
    expect(first).toBeNull();
    const last = await getConflictBackup(keys[11]!);
    expect(last).toEqual(bytes(11));

    // The other database is untouched.
    const otherKeys = (await Promise.all(keys.map((key) => getConflictBackup(key)))).filter(
      (value) => value !== null,
    );
    expect(otherKeys).toHaveLength(10);
  });
});
